const input = $input.item.json;
const text = input.text || '';

function extract(pattern) {
  return text.match(pattern)?.[1]?.trim() || null;
}

function toISO(value) {
  if (!value) return null;

  const months = {
    january: '01', february: '02', march: '03',
    april: '04', may: '05', june: '06',
    july: '07', august: '08', september: '09',
    october: '10', november: '11', december: '12',
  };

  const match = value.match(
    /^(\d{1,2})\s+([a-z]+)\s+(\d{4})$/i
  );

  if (!match) return null;

  const month = months[match[2].toLowerCase()];
  if (!month) return null;

  return `${match[3]}-${month}-${match[1].padStart(2, '0')}`;
}

const documentId = extract(
  /\bDocument ID\s*:?\s*(DOC-[A-Z]+-\d+|[A-Z]{2,4}-\d{3})\b/i
);

const revision = extract(
  /\bRevision\s*:?\s*(\d+)\b/i
);

const effectiveDate = extract(
  /\bEffective Date\s*:?\s*(\d{1,2}\s+[A-Za-z]+\s+\d{4})/i
);

const expirationDate = extract(
  /\bExpiration Date\s*:?\s*(\d{1,2}\s+[A-Za-z]+\s+\d{4})/i
);

const status = extract(
  /\bStatus\s*:?\s*(Current|Expired|Superseded|Draft)\b/i
);

const documentType = extract(
  /\bDocument Type\s*:?\s*(.+?)(?=\s+Product Family\b|\s+Authority Class\b|\n|$)/i
);

const productFamily = extract(
  /\bProduct Family\s*:?\s*([^\n]+)/i
);

const documentTypeOverrides = {
  'CP-004': 'compatibility_guide',
  'PT-010': 'product_guide',
  'PT-011': 'installation_guide',
};


const agreementId = extract(
  /\bAgreement ID\s*:?\s*(AGR-\d{4}-\d+)\b/i
);

const normalizedDocumentType = documentType
  ?.toLowerCase()
  .replace(/\s+/g, '_')
  || (agreementId ? 'customer_agreement' : null)
  || documentTypeOverrides[documentId]
  || null;

const accountId = extract(
  /\bAccount ID\s*:?\s*(ACC-\d+)\b/i
);

const agreementStatus = extract(
  /\bagreement\s+(ACTIVE|EXPIRED|TERMINATED|INACTIVE)\b/i
);

return {
  json: {
    document_id: documentId,
    document_type: normalizedDocumentType,
    agreement_id: agreementId,
account_id: accountId,
agreement_status: agreementStatus?.toUpperCase() || null,
    version: revision,
    effective_date: toISO(effectiveDate),
    expiration_date: toISO(expirationDate),
    status: status?.toUpperCase() || null,
    product_family: productFamily,
    content: text,
  },
};

const items = $input.all();
const expectedCount = 28;
const errors = [];
const seenIds = new Set();

if (items.length !== expectedCount) {
  errors.push(
    `Expected ${expectedCount} documents, got ${items.length}`
  );
}

for (const [index, item] of items.entries()) {
  const doc = item.json;
  const label = doc.document_id || `Item ${index + 1}`;

  for (const field of [
    'document_id',
    'document_type',
    'version',
    'status',
    'content',
  ]) {
    if (
      typeof doc[field] !== 'string' ||
      !doc[field].trim()
    ) {
      errors.push(`${label}: missing ${field}`);
    }
  }

  if (doc.document_id) {
    if (seenIds.has(doc.document_id)) {
      errors.push(`${label}: duplicate document_id`);
    }
    seenIds.add(doc.document_id);
  }

  if (
    typeof doc.content === 'string' &&
    doc.content.trim().length < 100
  ) {
    errors.push(`${label}: content too short`);
  }

  for (const field of [
    'effective_date',
    'expiration_date',
  ]) {
    const value = doc[field];

    if (
      value != null &&
      !/^\d{4}-\d{2}-\d{2}$/.test(value)
    ) {
      errors.push(`${label}: invalid ${field}`);
    }
  }

  if (doc.agreement_id && !doc.account_id) {
    errors.push(`${label}: agreement missing account_id`);
  }
}

if (errors.length > 0) {
  throw new Error(
    `Knowledge validation failed:\n${errors.join('\n')}`
  );
}

return items;

const doc = $input.item.json;

// Metadata wajib
const metadata = {
  document_id: doc.document_id,
  document_type: doc.document_type,
  version: doc.version,
  status: doc.status,
};

// Metadata opsional
const optionalFields = [
  'effective_date',
  'expiration_date',
  'agreement_id',
  'account_id',
  'agreement_status',
  'product_family',
];

for (const field of optionalFields) {
  const value = doc[field];

  if (
    value !== null &&
    value !== undefined &&
    value !== ''
  ) {
    metadata[field] = value;
  }
}

return {
  json: {
    metadata,
    content: doc.content,
  },
};
